const express = require('express');
const { requireFirebaseAuth } = require('../middleware/auth.middleware');
const { requireRole } = require('../middleware/role.middleware');
const {
  getPendingSellers,
  approveSeller,
  rejectSeller
} = require('../controllers/seller.controller');
const {
  getPendingProducts,
  getApprovedProductsForAdmin,
  getRejectedProductsForAdmin,
  getAdminProductById,
  approveProduct,
  rejectProduct,
  setUserRoleByAdmin
} = require('../controllers/product.controller');

const router = express.Router();

// All admin routes require Firebase auth + admin role
router.use(requireFirebaseAuth, requireRole('admin'));

// Seller application review
router.get('/sellers/pending', getPendingSellers);
router.patch('/sellers/:sellerId/approve', approveSeller);
router.patch('/sellers/:sellerId/reject', rejectSeller);

// Product review
router.get('/products/pending', getPendingProducts);
router.get('/products/approved', getApprovedProductsForAdmin);
router.get('/products/rejected', getRejectedProductsForAdmin);
router.get('/products/:productId', getAdminProductById);
router.patch('/products/:productId/approve', approveProduct);
router.patch('/products/:productId/reject', rejectProduct);

// User role assignment
router.patch('/users/:uid/role', setUserRoleByAdmin);

module.exports = router;
